<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:9px;color:#111}h1{font-size:16px}h2{font-size:12px;margin:14px 0 5px}table{width:100%;border-collapse:collapse;margin-bottom:10px}th,td{border:1px solid #bbb;padding:4px;vertical-align:top;word-break:break-word}th{background:#eee}.metadata th{width:22%;text-align:left}</style></head><body><h1>{{ $title }}</h1><h2>Report context</h2><table class="metadata"><tbody>@foreach($metadata as $label => $value)<tr><th>{{ $label }}</th><td>{{ is_array($value)||is_object($value) ? json_encode($value, JSON_UNESCAPED_SLASHES) : $value }}</td></tr>@endforeach</tbody></table><h2>Report data</h2><table><thead><tr>@foreach($columns as $column)<th>{{ $column }}</th>@endforeach</tr></thead><tbody>@foreach($rows as $row)<tr>@foreach($columns as $column)<td>{{ is_array($row[$column]??null)||is_object($row[$column]??null) ? json_encode($row[$column], JSON_UNESCAPED_SLASHES) : ($row[$column]??'') }}</td>@endforeach</tr>@endforeach</tbody></table></body></html>
